# gaddr_src.inc for the layer, from the source build's symbols
import re
sym = {}
for l in open('out/sym.txt'):
    m = re.match(r'(\S+): (?:EQU )?0x([0-9A-F]+)', l)
    if m: sym[m.group(1)] = int(m.group(2), 16)
p0 = open('out/p0.bin', 'rb').read()
xg = p0[sym['l_ASMBL2'] - 0xC000:][:6]
lst = open('out/main.lst', encoding='cp866', errors='replace').read()
geo = int(re.search(r'\+\+([0-9A-F]{4}) 3A [0-9A-F]{2} [0-9A-F]{2}\s+LD A,\(l_xHAC2\)', lst).group(1), 16)
names = dict(G_MOUSE='l_MOUSE', G_COORD='l_COORD', G_OLDCO='l_OLDCO', G_CONTRB='l_CONTRB', G_HAC2='l_xHAC2',
             G_TTYPE='l_T_TYPE', G_TUFO='l_T_UFO', G_TINTR='l_T_INTR', G_BATTLE='l_BATTLE', G_BATTL1='l_BATTL1',
             G_MEM7='l_MEM7', G_PT128='l_PT128', G_KEYS='l_KEYS', G_KBR='l_KBR', G_KEYJOY='l_KEYJOY',
             G_PMOUSE='l_PMOUSE', G_EI='l_E_I', G_YN='l_YES_NO', DELPC='l_DELPC', DLPCB='l_DLPCB', xpD0='l_xpD0', G_MWINX='l_MWINX', G_SELAT1='l_SELAT1', G_SCOSCR='l_SCOSCR', G_BCOSCR='l_BCOSCR', G_OUTDSC='l_OUTDSC', G_AQU='l_AQU', G_AQNAVT='l_AQNAVT', G_INDLS='l_IND_LS', G_RS='l_RS', G_RNUM='l_R_NUM', G_MONEY='l_MONEY', G_SGUN='l_S_GUN', G_SDUM='l_S___', G_STMP='l_S_TMP', G_RSN='l_RSN', G_HERAD='l_HER_AD', G_GTIME='l_G_TIME', G_CANFB='l_CANF_B', G_LADIM='l_LA_DIM', G_WORDSP='l__words', G_NAMES='l_NAMES', G_WORDS='l_WORDS', G_TWCMPR='l_TWCMPR', G_MAN='l_MAN', G_PNAM='l_PNAM', G_RRT='l_RRT', G_LRT='l_LRT', G_DRT='l_DRT', G_URT='l_URT', G_HIX='l_HIX', G_DATR='l_DATR', G_HE1='l_HE1', G_DSP0='l_DSP0', G_DSP2='l_DSP2', G_DSP4='l_DSP4', G_DSP6='l_DSP6', G_GBAD='l_GB_AD', G_GBUH='l_GBUH', G_ALLSH='l_ALLSH', G_ALLSE='l_ALLSE', G_MSIRET='l_MSiRET', G_PBUH='l_PBUH', G_LS2='l_LS2', G_RS2='l_RS2', G_xHERO='l_xHERO', G_xMARKE='l_xMARKE', G_xDIE='l_xDIE', G_PIMG='l_PIMG', G_FLR='l_FLR', G_X0='l_X0', G_SH='l_SH', G_SEED='l_SEED', G_PPX='l_PPX', G_PAD='l_P_AD', G_PVIS='l_PVIS', G_BX='l_BX', G_FIRTYP='l_FIRTYP', G_BULL='l_BULL', G_BATRET='l_BATRET', G_CHNGRG='l_CHNGRG', G_COLOR='l_COLOR', G_LMOD='l_L_MOD', G_xBUM='l_xBUM', G_EIDI='l_EIDI', G_DLDI='l_DLDI', G_MS20='l_MS20', G_LL2='l_L_L2', G_LLAND='l_L_LAND', G_LLL='l_L_LL', G_TTYPEX='l_T_TYPE', G_PRINR='l_PRINR', G_LETR='l_LETR', G_TALR='l_TALR', G_TIM='l_TIM', G_PERIOD='l_PERIOD', G_FONT='l_FONT', G_INTR='l_INTR', G_UFO='l_UFO', G_UFOV='l_UFOV', G_TSHP='l_T_SHP', G_BASE='l_BASE', G_XBASE='l_XBASE', G_TM='l_T_M', G_TD='l_T_D', G_SWST='l_SWST', G_SPM='l_SPM', G_START='l_start')
out = ['; game addresses: the build from the sources (generated by build/gen_gaddr.py)']
for k, v in names.items(): out.append('%-8s equ #%04X' % (k, sym[v]))
out.append('G_BMOVR  equ #%04X                ; (BMOV_: after its CALL CONTR - the poll from the fight\'s loop)' % (sym['l_BMOV_'] + 9))
out.append('G_CONTRJ equ 0\nG_GEO1  equ #%04X' % geo)
out.append('        MACRO XG_PAT\n        db %s\n        ENDM' % ','.join('#%02X' % b for b in xg))
import zlib
crc = zlib.crc32(open('out/b2.bin', 'rb').read() + open('out/b5.bin', 'rb').read()) & 0xFFFF
out.append('G_BUILD  equ #%04X                ; (UFO2.BTL: the game code in it must be this build\'s - ovl.asm dk_*)' % crc)
open('../port/gaddr_src.inc', 'w').write('\n'.join(out) + '\n')
print('\n'.join(out))
